-- Detailhandel (Detailhandelsfachfrau/Detailhandelsfachmann EFZ):
-- Bildungsplan-Fragenkatalog (16 × 30 Fragen).
-- Idempotent, additiv und ohne Datenverlust:
--   * course_key-CHECK-Constraints werden auf
--     abu/automechaniker/detailhandel/fage/informatiker/kv/schreiner/strassenbau erweitert.
--   * Module werden nach (course_key, title) gesucht oder angelegt.
--   * Lektionen werden nach (module_id, title) gesucht oder angelegt;
--     position/pass_score werden gesetzt.
--   * Fragen werden positionsbasiert UPSERTet: vorhandene (lesson_id,
--     position) werden aktualisiert (question.id bleibt erhalten, FKs zu
--     question_xp_awards / battle_answers bleiben intakt). Fehlende
--     Positionen werden eingefügt. Positionen > 30 werden entfernt.
--   * Profile, lesson_progress, lesson_attempts werden nicht angetastet.

begin;

-- ============================================================
-- 1) course_key-CHECK-Constraints erweitern
-- ============================================================
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'profiles_active_course_key_ck') then
    alter table public.profiles drop constraint profiles_active_course_key_ck;
  end if;
  alter table public.profiles
    add constraint profiles_active_course_key_ck check (active_course_key in ('abu', 'automechaniker', 'detailhandel', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if exists (select 1 from pg_constraint where conname = 'modules_course_key_ck') then
    alter table public.modules drop constraint modules_course_key_ck;
  end if;
  alter table public.modules
    add constraint modules_course_key_ck check (course_key in ('abu', 'automechaniker', 'detailhandel', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if to_regclass('public.battle_matches') is not null then
    if exists (select 1 from pg_constraint where conname = 'battle_matches_course_key_ck') then
      alter table public.battle_matches drop constraint battle_matches_course_key_ck;
    end if;
    alter table public.battle_matches
      add constraint battle_matches_course_key_ck check (course_key in ('abu', 'automechaniker', 'detailhandel', 'fage', 'informatiker', 'kv', 'schreiner', 'strassenbau'));
  end if;
end$$;

-- ============================================================
-- 2) DETAILHANDEL: 1 Modul, 16 Lektionen je 30 Fragen
-- ============================================================
do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin
  select id into v_module_id from public.modules where course_key = 'detailhandel' and title = 'Detailhandelsfachfrau/Detailhandelsfachmann EFZ – Bildungsplan' limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Detailhandelsfachfrau/Detailhandelsfachmann EFZ – Bildungsplan', 'Bildungsplan Detailhandelsfachfrau/Detailhandelsfachmann EFZ (BDS/SBFI). 16 Lektionen entlang der Handlungskompetenzbereiche zu Kundenbeziehungen, Warenbewirtschaftung, Produkt- und Dienstleistungskenntnissen, Betrieb und Branche sowie Einkaufserlebnissen inklusive Online-Shop.', 'detailhandel', 100)
    returning id into v_module_id;
  else
    update public.modules set description = 'Bildungsplan Detailhandelsfachfrau/Detailhandelsfachmann EFZ (BDS/SBFI). 16 Lektionen entlang der Handlungskompetenzbereiche zu Kundenbeziehungen, Warenbewirtschaftung, Produkt- und Dienstleistungskenntnissen, Betrieb und Branche sowie Einkaufserlebnissen inklusive Online-Shop.', position = 100 where id = v_module_id;
  end if;

  -- Lektion L01: L01 – Erster Kundenkontakt und Kommunikation
  select id into v_lesson_id from public.lessons where module_id = v_module_id and title = 'L01 – Erster Kundenkontakt und Kommunikation' limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'L01 – Erster Kundenkontakt und Kommunikation', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage beschreibt das Thema erster Kundenkontakt im Beruf Detailhandelsfachfrau/Detailhandelsfachmann EFZ am besten?', option_a = 'Kundinnen und Kunden freundlich, aufmerksam und situationsgerecht begrüssen', option_b = 'Kunden ignorieren im konkreten Auftrag im normalen Praxisalltag', option_c = 'nur bei Kaufabsicht grüssen im üblichen Arbeitsumfeld', option_d = 'Blickkontakt vermeiden im laufenden Tagesgeschäft bei sachgemässem Ablauf', correct_option = 'A', explanation = 'Der erste Kontakt prägt die Beziehung und das Einkaufserlebnis.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema erster Kundenkontakt im Beruf Detailhandelsfachfrau/Detailhandelsfachmann EFZ am besten?', 'Kundinnen und Kunden freundlich, aufmerksam und situationsgerecht begrüssen', 'Kunden ignorieren im konkreten Auftrag im normalen Praxisalltag', 'nur bei Kaufabsicht grüssen im üblichen Arbeitsumfeld', 'Blickkontakt vermeiden im laufenden Tagesgeschäft bei sachgemässem Ablauf', 'A', 'Der erste Kontakt prägt die Beziehung und das Einkaufserlebnis.', 1); end if;
  update public.questions set prompt = 'Worauf muss man beim Thema erster Kundenkontakt in der Praxis besonders achten?', option_a = 'Kunden ignorieren im üblichen Berufsalltag im Rahmen der Routine', option_b = 'Kundinnen und Kunden freundlich, aufmerksam und situationsgerecht begrüssen', option_c = 'nur bei Kaufabsicht grüssen unter typischen Arbeitsbedingungen', option_d = 'Blickkontakt vermeiden nach gängiger Praxis bei vergleichbaren Aufgaben', correct_option = 'B', explanation = 'Der erste Kontakt prägt die Beziehung und das Einkaufserlebnis.' where lesson_id = v_lesson_id and position = 2;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Worauf muss man beim Thema erster Kundenkontakt in der Praxis besonders achten?', 'Kunden ignorieren im üblichen Berufsalltag im Rahmen der Routine', 'Kundinnen und Kunden freundlich, aufmerksam und situationsgerecht begrüssen', 'nur bei Kaufabsicht grüssen unter typischen Arbeitsbedingungen', 'Blickkontakt vermeiden nach gängiger Praxis bei vergleichbaren Aufgaben', 'B', 'Der erste Kontakt prägt die Beziehung und das Einkaufserlebnis.', 2); end if;
  update public.questions set prompt = 'Welche Aussage zum Thema erster Kundenkontakt ist fachlich korrekt?', option_a = 'Kunden ignorieren im üblichen Arbeitsumfeld im normalen Betriebsablauf', option_b = 'nur bei Kaufabsicht grüssen bei sachgemässem Ablauf im üblichen Berufsalltag', option_c = 'Kundinnen und Kunden freundlich, aufmerksam und situationsgerecht begrüssen', option_d = 'Blickkontakt vermeiden im normalen Praxisalltag bei sachgemässer Ausführung', correct_option = 'C', explanation = 'Der erste Kontakt prägt die Beziehung und das Einkaufserlebnis.' where lesson_id = v_lesson_id and position = 3;
